	@Test
	void transientDictionaryAndLowLevelClearKeepOwnerDialect() throws Exception {
		Path fixture = directory.resolve("fixture");
		extract("v6-dictionary-ordered.zip", fixture);
		StoreProperties properties = new StoreProperties(fixture.toFile());
		properties.load();
		var config = config(false);
		var format = LmdbStoreFormat.fromProperties(properties, config);
		Path transientDirectory = directory.resolve("transient");
		Files.createDirectories(transientDirectory);
		var emptyProperties = new StoreProperties(transientDirectory.toFile());
		LmdbSailStore owner = new LmdbSailStore(transientDirectory.toFile(), emptyProperties, config, false, format,
				true);
		try {
			ValueStore values = (ValueStore) owner.getValueFactory();
			var literal = VF.createLiteral("dictionary:" + "x".repeat(100));
			values.startTransaction(true);
			long before = values.storeValue(literal);
			values.commit();
			assertEquals(ValueIds.T_CORE_LITERAL, ValueIds.getIdType(before));
			values.clear();
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(literal));
			values.startTransaction(true);
			long after = values.storeValue(VF.createLiteral("after clear"));
			values.commit();
			assertEquals(ValueIds.T_CORE_LITERAL, ValueIds.getIdType(after));
			assertEquals(6, values.getFormat().getVersion());
		} finally {
			owner.close();
		}
		assertArrayEquals(new byte[] { 6 }, nativeGet(transientDirectory, "gc_meta", new byte[] { 3 }));
	}

	@Test
	void nativeCommitThenLogicalRollbackKeepsDependencyCounts() throws Exception {
		Path fixture = directory.resolve("fixture");
		extract("v6-dictionary-ordered.zip", fixture);
		StoreProperties properties = new StoreProperties(fixture.toFile());
		properties.load();
		var config = config(false);
		config.setAutoGrow(true);
		config.setValueDBSize(24 * 1024);
		var format = LmdbStoreFormat.fromProperties(properties, config);
		Path dictionary = directory.resolve("owned");
		Files.createDirectories(dictionary);
		var local = new StoreProperties(dictionary.toFile());
		var literal = VF.createLiteral("live core component " + "y".repeat(1024));
		var predicate = VF.createIRI("urn:commit:predicate");
		var subject = VF.createIRI("urn:commit:subject");
		var inner = VF.createTripleTerm(subject, predicate, literal);
		var outer = VF.createTripleTerm(VF.createIRI("urn:commit:outer"), predicate, inner);
		ValueStore values = new ValueStore(dictionary.resolve("values").toFile(), local, config, format, true,
				ValueStore.Initialization.STANDALONE_DICTIONARY);
		try {
			values.startTransaction(true);
			long outerId = values.storeValue(outer);
			long literalId = values.getId(literal);
			// This is the actual native-commit method used by map growth, followed by a logical abort.
			values.endTransaction(true, true);
			values.startTransaction(false);
			values.storeValue(VF.createLiteral("rolled back"));
			values.rollback();
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(VF.createLiteral("rolled back")));
			values.startTransaction(true);
			values.gcIds(List.of(literalId, values.getId(inner), values.getId(subject)),
					new HashSet<>());
			values.commit();
			assertEquals(outer, values.getValue(outerId));
			assertNotEquals(LmdbValue.UNKNOWN_ID, values.getId(literal));
		} finally {
			values.close();
		}
		values = new ValueStore(dictionary.resolve("values").toFile(), local, config, format);
		try {
			assertNotEquals(LmdbValue.UNKNOWN_ID, values.getId(outer));
			assertEquals(literal, values.getValue(values.getId(literal)));
		} finally {
			values.close();
		}
		assertArrayEquals(new byte[] { 6 }, nativeGet(dictionary, "gc_meta", new byte[] { 3 }));
	}

	@Test
	void ownedLearnerFilesArePreservedOutsideForwardResetDirectory() throws Exception {
		extract("v6-inline-ordered.zip", directory);
		byte[] cost = ByteBuffer.allocate(16).putInt(0x4C4E434D).putInt(1).putLong(12345).array();
		byte[] sketch = ByteBuffer.allocate(16).putInt(0x524A4544).putInt(2).putLong(6789).array();
		byte[] filter = ByteBuffer.allocate(12).putInt(3).putLong(9876).array();
		Files.write(directory.resolve("cost-model.lncm"), cost);
		Files.createDirectories(directory.resolve("join-estimator.rjes"));
		Files.write(directory.resolve("join-estimator.rjes/metadata.bin"), sketch);
		Files.write(directory.resolve("join-estimator.rjes.filters"), filter);
		var repository = repository(directory, true);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertArrayEquals(cost, Files.readAllBytes(directory.resolve("cost-model.lncm")));
			connection.begin(IsolationLevels.NONE);
			connection.add(VF.createIRI("urn:rolled:back"), VF.createIRI("urn:p"), VF.createLiteral("rollback"));
			connection.prepare();
			connection.rollback();
			assertFalse(Files.exists(directory.resolve("cost-model.lncm")));
			assertFalse(Files.exists(directory.resolve("join-estimator.rjes/metadata.bin")));
			assertFalse(Files.exists(directory.resolve("join-estimator.rjes.filters")));
			assertArchived("cost-model.lncm", cost);
			assertArchived("join-estimator.rjes.metadata.bin", sketch);
			assertArchived("join-estimator.rjes.filters", filter);
			LmdbV6InteroperabilityTest.maintenanceWrite(connection);
			assertArchived("cost-model.lncm", cost);
		} finally {
			repository.shutDown();
		}
		String classpath = System.getProperty("rdf4j.lmdb.compat.producerClasspath");
		if (classpath != null) {
			run(classpath, "LmdbV6FixtureProducer", "verify-accelerated", true, true);
			assertArchived("cost-model.lncm", cost);
			assertArchived("join-estimator.rjes.metadata.bin", sketch);
			assertArchived("join-estimator.rjes.filters", filter);
		}
	}

	@Test
	void unknownLearnerSchemaPreventsMutationAndPreservesBytes() throws Exception {
		extract("v6-inline-ordered.zip", directory);
		byte[] unknown = ByteBuffer.allocate(8).putInt(0x4C4E434D).putInt(99).array();
		Files.write(directory.resolve("cost-model.lncm"), unknown);
		var repository = repository(directory, true);
		repository.init();
		try (var connection = repository.getConnection()) {
			long before = LmdbV6InteroperabilityTest.count(connection, false);
			assertThrows(RuntimeException.class, () -> {
				connection.begin();
				connection.add(VF.createIRI("urn:blocked"), VF.createIRI("urn:p"), VF.createLiteral("blocked"));
				connection.commit();
			});
			if (connection.isActive()) {
				connection.rollback();
			}
			assertEquals(before, LmdbV6InteroperabilityTest.count(connection, false));
			assertArrayEquals(unknown, Files.readAllBytes(directory.resolve("cost-model.lncm")));
		} finally {
			repository.shutDown();
		}
	}

