	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void genuineNewV2IsWritableByUnpatchedMaintenanceBinary(boolean inline) throws Exception {
		String classpath = System.getProperty("rdf4j.lmdb.compat.legacyClasspath");
		assumeTrue(classpath != null, "Local frozen unpatched binary is supplied by the verification worker");
		var repository = repository(directory, inline);
		repository.init();
		try (var connection = repository.getConnection()) {
			var predicate = VF.createIRI("urn:v2:predicate");
			var literal = VF.createLiteral("shared custom value",
					VF.createIRI("urn:v2:shared-custom-datatype"));
			var inner = VF.createTripleTerm(VF.createBNode("shared-v2-bnode"), predicate, literal);
			connection.begin();
			connection.add(VF.createIRI("urn:v2:first"), predicate,
					VF.createTripleTerm(VF.createIRI("urn:v2:outer"), predicate, inner));
			connection.add(VF.createIRI("urn:v2:second"), predicate, inner, VF.createIRI("urn:v2:graph"));
			connection.add(VF.createBNode("shared-v2-bnode"), predicate, literal);
			connection.add(VF.createIRI("urn:v2:maintenance"), predicate, VF.createLiteral("maintenance write"));
			List<Literal> literals = v2Literals();
			for (int i = 0; i < literals.size(); i++) {
				connection.add(VF.createIRI("urn:v2:lexical:" + i), predicate, literals.get(i));
			}
			connection.commit();
		} finally {
			repository.shutDown();
		}
		assertEquals("2", properties(directory, "store.properties").getProperty("version"));
		assertFalse(Files.exists(directory.resolve("lmdbrdf.ver")));
		run(classpath, "LmdbMaintenanceInteropProcess", "verify", inline, false);
		run(classpath, "LmdbMaintenanceInteropProcess", "mutate", inline, false);
		repository = repository(directory, inline);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertTrue(connection.hasStatement(VF.createIRI("urn:v2:legacy-writer"), null, null, false));
			assertV2Lexicals(connection, "urn:v2:lexical:");
			assertV2Lexicals(connection, "urn:v2:legacy-lexical:");
			connection.begin();
			connection.remove(VF.createIRI("urn:v2:first"), null, null);
			connection.commit();
			assertTrue(connection.hasStatement(VF.createIRI("urn:v2:second"), null, null, false));
		} finally {
			repository.shutDown();
		}
	}

	private static List<Literal> v2Literals() {
		return List.of(VF.createLiteral("42", CoreDatatype.XSD.INT),
				VF.createLiteral("+0042", CoreDatatype.XSD.INT), VF.createLiteral("-42", CoreDatatype.XSD.INT),
				VF.createLiteral("42.00", CoreDatatype.XSD.DECIMAL),
				VF.createLiteral("2026-10-03T12:00:01Z", CoreDatatype.XSD.DATETIME),
				VF.createLiteral("2026-10-03T12:00:01.0Z", CoreDatatype.XSD.DATETIME),
				VF.createLiteral("2026-10-03T12:00:01.00Z", CoreDatatype.XSD.DATETIME),
				VF.createLiteral("2026-10-03T12:00:01.000Z", CoreDatatype.XSD.DATETIME),
				VF.createLiteral("2026-10-03T12:00:01.123", CoreDatatype.XSD.DATETIME),
				VF.createLiteral("2026-10-03T12:00:01+13:37", CoreDatatype.XSD.DATETIME),
				VF.createLiteral("2026-10-03T12:00:01.00Z", CoreDatatype.XSD.DATETIMESTAMP),
				VF.createLiteral("2026-10-03Z", CoreDatatype.XSD.DATE),
				VF.createLiteral("2026-10-03+13:37", CoreDatatype.XSD.DATE));
	}

	private static void assertV2Lexicals(RepositoryConnection connection, String prefix) {
		List<Literal> literals = v2Literals();
		Set<Literal> actual = new HashSet<>();
		for (int i = 0; i < literals.size(); i++) {
			Literal expected = literals.get(i);
			try (var rows = connection.getStatements(VF.createIRI(prefix + i), VF.createIRI("urn:v2:predicate"),
					null, false)) {
				assertTrue(rows.hasNext(), prefix + i);
				Literal found = (Literal) rows.next().getObject();
				assertEquals(expected.getLabel(), found.getLabel(), prefix + i);
				assertEquals(expected.getDatatype(), found.getDatatype(), prefix + i);
				assertFalse(rows.hasNext(), prefix + i);
				actual.add(found);
			}
			assertTrue(connection.hasStatement(VF.createIRI(prefix + i), VF.createIRI("urn:v2:predicate"),
					expected, false), prefix + i);
		}
		assertEquals(literals.size(), actual.size());
	}

	private void assertArchived(String prefix, byte[] bytes) throws IOException {
		try (var files = Files.list(directory)) {
			var matches = files.filter(path -> path.getFileName().toString().startsWith(prefix + ".maintenance-"))
					.toList();
			assertEquals(1, matches.size());
			assertArrayEquals(bytes, Files.readAllBytes(matches.get(0)));
		}
	}

	private void run(String classpath, String main, String phase, boolean inline, boolean ordered) throws Exception {
		Path log = directory.resolveSibling(directory.getFileName() + "-" + phase + ".log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-cp", classpath, "org.eclipse.rdf4j.sail.lmdb." + main, phase, directory.toString(),
				Boolean.toString(inline), Boolean.toString(ordered)).redirectErrorStream(true)
				.redirectOutput(log.toFile())
				.start();
		assertEquals(0, process.waitFor(), () -> "Separate binary failed; see " + log);
	}
